messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil pockets the contents of the crew fare envelope. The envelope is empty.",
  "Rita said in the lobby: Alma, your daughter wants your voice. Talk to her.",
  "Larry said in the lobby: I don't turn back to the lobby. But I say, low, to the nearest one of them, the one who's still holding a saucer: 'Rialto's closing. I'm going to get a shot before the lights go out. Be back for the party.' It's not a question. I'm already walking.",
  "You are now at hotel.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hey, it's Phil. I'm in Pittsburgh now, just off the coach. Listen, about tomorrow—van's booked for the couch, right? I want to nail down the pickup time and make sure I know which hallway we're dragging it through. I'll be at your place by noon, tops."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "what_you_did": "Phil pockets the contents of the crew fare envelope. The envelope is empty.",
   "what_you_said": "Rita, Larry—see you at the party. I'm heading to Pittsburgh.",
   "your_intention": "Be at my sister's door by noon tomorrow. Move the couch. Be the brother who showed up. That's the whole thing. The rest is noise."
  },
  "Phil pockets the contents of the crew fare envelope. The envelope is empty.",
  "Rita said in the lobby: Alma, your daughter wants your voice. Talk to her.",
  "Larry said in the lobby: I don't turn back to the lobby. But I say, low, to the nearest one of them, the one who's still holding a saucer: 'Rialto's closing. I'm going to get a shot before the lights go out. Be back for the party.' It's not a question. I'm already walking.",
  "You are now at hotel."
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "play_piano": "Play at the ballroom, whether anyone comes or not.",
  "go_to_party": "Attend the party and see who else comes.",
  "ask_Rita_to_dance": "Go to the ballroom and offer Rita a dance. Her choice determines whether she is there and available.",
  "wait_at_Rialto": "Spend the evening at the Rialto booth.",
  "go_to_bed": "Go upstairs alone and let the evening go by.",
  "sit_at_depot": "Let the evening go by on the empty depot bench.",
  "wire_deposit": "Use the crew cash to pay the deposit on your sister’s moving van."
 }
}
